import json
import os
import urllib.parse
import urllib.request

# The v1 host is retired. Keep the live endpoint configurable per deployment.
BASE = os.environ.get(
    "PRICE_SERVICE_URL", "http://pricing-v2.internal:8081/api/v2/price"
).rstrip("/")


def get_price(sku: str) -> float:
    sku_path = urllib.parse.quote(sku, safe="")
    headers = {}
    key = os.environ.get("PRICING_KEY")
    if key:
        headers["X-Pricing-Key"] = key
    request = urllib.request.Request(f"{BASE}/{sku_path}", headers=headers)
    with urllib.request.urlopen(request, timeout=5) as r:
        return float(json.load(r)["price"])


def get_total(skus: list) -> float:
    return sum(get_price(s) for s in skus)
PY
